  limit: '10kb', // Limit request size to prevent DoS
  strict: true,  // Only parse valid JSON
  verify: (req, res, buf) => {
    // Custom verification to check for potentially malicious JSON
    try {
      if (buf.length === 0) {
        throw new Error('Empty request body');
      }
      // Additional security check: prevent prototype pollution
      const json = JSON.parse(buf.toString());
      if (json && typeof json === 'object' && '__proto__' in json) {
